L159: /* Return true if FTRY (the candidate suffix) matches NAME.  If
L160:    IS_FILENAME is true, the check is simply that FTRY is a suffix of
L161:    NAME.  If false (that is, NAME is a format), then FTRY and NAME must
L162:    be entirely equal.  */
L163: static boolean
L164: try_suffix (boolean is_filename, string name, unsigned name_len,
L165:             const_string ftry)
L166: {
L167:   unsigned try_len;
L168: 
L169:   if (!ftry || ! *ftry) {
L170:     return false;
L171:   }
L172: 
L173:   try_len = strlen (ftry);
L174:   if (try_len > name_len) {
L175:     /* Candidate is longer than what we're looking for.  */
L176:     return false;
L177:   }
L178:   if (!is_filename && try_len < name_len) {
L179:     /* We're doing format names, not file names, and candidate is
L180:        shorter than what we're looking for.  E.g., do not find `lua'
L181:        when looking for `clua'.  */
L182:     return false;
L183:   }
L184: 
L185:   if (FILESTRCASEEQ (name + name_len - try_len, ftry)) {
L186:     return true;
L187:   }
L188: 
L189:   return false;
L190: }
