L194: /* Use the file type from -format if that was previously determined
L195:    (i.e., the user_format global variable), else guess dynamically from
L196:    NAME.  Return kpse_last_format if undeterminable.  This function is
L197:    also used to parse the -format string, a case we distinguish via
L198:    is_filename being false.
L199: 
L200:    A few filenames have been hard-coded for format types that
L201:    differ from what would be inferred from their extensions. */
L202: static kpse_file_format_type
L203: find_format (kpathsea kpse, string name, boolean is_filename)
L204: {
L205:   kpse_file_format_type ret = kpse_last_format;
L206: 
L207:   if (is_filename && user_format != kpse_last_format) {
L208:     ret = user_format; /* just return what we already computed */
L209:   } else if (FILESTRCASEEQ (name, "config.ps")) {
L210:     ret = kpse_dvips_config_format;
L211:   } else if (FILESTRCASEEQ (name, "dvipdfmx.cfg")) {
L212:     ret = kpse_program_text_format;
L213:     kpathsea_set_program_name (kpse, argv0, progname ? progname : "dvipdfmx");
L214:   } else if (FILESTRCASEEQ (name, "fmtutil.cnf")) {
L215:     ret = kpse_web2c_format;
L216:   } else if (FILESTRCASEEQ (name, "glyphlist.txt")) {
L217:     ret = kpse_fontmap_format;
L218:   } else if (FILESTRCASEEQ (name, "mktex.cnf")) {
L219:     ret = kpse_web2c_format;
L220:   } else if (FILESTRCASEEQ (name, "pdfglyphlist.txt")) {
L221:     ret = kpse_fontmap_format;
L222:   } else if (FILESTRCASEEQ (name, "pdftex.cfg")) {
L223:     ret = kpse_pdftex_config_format;
L224:   } else if (FILESTRCASEEQ (name, "texglyphlist.txt")) {
L225:     ret = kpse_fontmap_format;
L226:   } else if (FILESTRCASEEQ (name, "texmf.cnf")) {
L227:     ret = kpse_cnf_format;
L228:   } else if (FILESTRCASEEQ (name, "updmap.cfg")) {
L229:     ret = kpse_web2c_format;
L230:   } else if (FILESTRCASEEQ (name, "XDvi")) {
L231:     ret = kpse_program_text_format;
L232:   } else {
L233:     if (!is_filename) {
L234:       /* Look for kpsewhich-specific format abbreviations.  */
L235:       ret = format_abbr (name);
L236:     }
L237:     if (ret == kpse_last_format) {
L238:       int f = 0;  /* kpse_file_format_type */
L239:       unsigned name_len = strlen (name);
L240: 
L241:       while (f != kpse_last_format) {
L242:         const_string *ext;
L243:         const_string ftry;
L244:         boolean found = false;
L245: 
L246:         if (!kpse->format_info[f].type)
L247:           kpathsea_init_format (kpse, (kpse_file_format_type) f);
L248: 
L249: /* Just to abbreviate this lengthy call.  */
L250: #define TRY_SUFFIX(ftry) try_suffix (is_filename, name, name_len, (ftry))
L251:         if (!is_filename) {
L252:           /* Allow the long name, but only in the format options.  We don't
L253:              want a filename confused with a format name.  */
L254:           ftry = kpse->format_info[f].type;
L255:           found = TRY_SUFFIX (ftry);
L256:         }
L257:         for (ext = kpse->format_info[f].suffix; !found && ext && *ext; ext++) {
L258:           found = TRY_SUFFIX (*ext);
L259:         }
L260:         for (ext=kpse->format_info[f].alt_suffix; !found && ext && *ext;ext++){
L261:           found = TRY_SUFFIX (*ext);
L262:         }
L263:         if (found)
L264:           break;
L265:         f++;
L266:       }
L267:       ret = f;
L268:     }
L269:   }
L270:   return ret;
L271: }
